function nfLeadPrepare(){
  var st=document.getElementById('lead-state');
  if(st&&!st.options.length){ st.innerHTML=NF_STATE_LIST.map(function(x){ return '<option value="'+x[0]+'"'+(x[1]==='UP'?' selected':'')+'>'+x[0]+'</option>'; }).join(''); }
  var dl=document.getElementById('nf-lead-districts'); if(!dl){ dl=document.createElement('datalist'); dl.id='nf-lead-districts'; document.body.appendChild(dl); }
  var fill=function(){ var code=(NF_STATE_LIST.find(function(x){ return x[0]===(st&&st.value); })||[])[1]; dl.innerHTML=(NF_DISTRICTS[code]||[]).map(function(n){ return '<option value="'+n+'">'; }).join(''); };
  fill(); if(st) st.onchange=function(){ fill(); var d=document.getElementById('lead-district'); if(d) d.value=''; };
  var set=function(id,k){ var el=document.getElementById(id); if(el) el.textContent=nfRegT(k); };
  var tt=document.getElementById('nf-lead-title'); if(tt) tt.textContent='🏛️ '+nfRegT('District / Bulk Enrollment');
  set('nf-lead-intro','Interested in enrolling multiple facilities under a district or organizational contract? Share your details and our team will reach out.');
  [['nf-lead-l-org','District / Organization Name *'],['nf-lead-l-state','State *'],['nf-lead-l-dist','District'],['nf-lead-dist-hint','Leave District blank if the enquiry covers several districts.'],['nf-lead-l-you','Your Name *'],['nf-lead-l-mob','Mobile Number *'],['nf-lead-l-count','Approx. Number of Facilities']].forEach(function(x){ set(x[0],x[1]); });
  var btn=document.querySelector('#lead-signup-body .fc-add-btn'); if(btn&&!btn.disabled) btn.innerHTML='<i class="ti ti-send" style="font-size:14px;"></i> '+nfRegT('Submit Enquiry');
  var cl=document.querySelector('#lead-signup-overlay .rm-cancel'); if(cl) cl.textContent=nfRegT('✕ Close');
}
function nfRegT(k){ return nfLvlText((typeof _appLang!=='undefined'&&_appLang==='hi'&&NF_REG_HI[k])||k); }
