function nfRegPrepare(){
  var st=document.getElementById('demo-fac-state');
  if(st&&!st.options.length){ st.innerHTML=NF_STATE_LIST.map(function(x){ return '<option value="'+x[0]+'"'+(x[1]==='UP'?' selected':'')+'>'+x[0]+'</option>'; }).join(''); }
  var dl=document.getElementById('nf-districts'); if(!dl){ dl=document.createElement('datalist'); dl.id='nf-districts'; document.body.appendChild(dl); }
  var fill=function(){ var code=(NF_STATE_LIST.find(function(x){ return x[0]===(st&&st.value); })||[])[1]; dl.innerHTML=(NF_DISTRICTS[code]||[]).map(function(n){ return '<option value="'+n+'">'; }).join(''); };
  fill(); if(st) st.onchange=function(){ fill(); var d=document.getElementById('demo-fac-district'); if(d) d.value=''; };
  var din=document.getElementById('demo-fac-district'); if(din) din.setAttribute('list','nf-districts');
  var set=function(id,k){ var el=document.getElementById(id); if(el) el.textContent=nfRegT(k); };
  set('nf-reg-title',''); var tt=document.getElementById('nf-reg-title'); if(tt) tt.textContent='🏥 '+nfRegT('Register your Sub-Centre');
  set('nf-reg-intro','The first 7 days (Baseline) are free. After that, the CHO pays to continue the 60-day programme.');
  [['nf-reg-l-name','Sub-Centre name *'],['nf-reg-l-dist','District *'],['nf-reg-l-state','State *'],['nf-reg-l-pkg','Package'],['nf-reg-l-you','Your name (CHO) *'],['nf-reg-l-mob','Mobile number *']].forEach(function(x){ set(x[0],x[1]); });
  var btn=document.querySelector('#demo-signup-body .fc-add-btn'); if(btn&&!btn.disabled) btn.innerHTML='<i class="ti ti-check" style="font-size:14px;"></i> '+nfRegT('Register');
  var cl=document.querySelector('#demo-signup-overlay .rm-cancel'); if(cl) cl.textContent=nfRegT('✕ Close');
}
